#include <iostream>
#include <vector>
#include <queue>
#include <string>

using namespace std;

/**
 * Problem: 22171 - Dungeon Master
 * 
 * 解題思路：
 * 1. 在一個 3D 地牢中尋找從起點 'S' 到終點 'E' 的最短路徑。
 * 2. 這是一個典型的最短路徑問題，可以使用廣度優先搜尋 (BFS) 來解決。
 * 3. 狀態由三維坐標 (l, r, c) 表示，分別代表層、行、列。
 * 4. 每次移動可以向上下南北東西六個方向。
 * 5. 使用一個三維陣列來記錄每個點是否已訪問過以及到達該點的距離。
 */

struct Point {
    int l, r, c, d;
};

int dl[] = {1, -1, 0, 0, 0, 0};
int dr[] = {0, 0, 1, -1, 0, 0};
int dc[] = {0, 0, 0, 0, 1, -1};

int main() {
    int L, R, C;
    while (cin >> L >> R >> C && (L || R || C)) {
        vector<vector<string>> dungeon(L, vector<string>(R));
        Point start, end;
        for (int i = 0; i < L; i++) {
            for (int j = 0; j < R; j++) {
                cin >> dungeon[i][j];
                for (int k = 0; k < C; k++) {
                    if (dungeon[i][j][k] == 'S') start = {i, j, k, 0};
                    if (dungeon[i][j][k] == 'E') end = {i, j, k, 0};
                }
            }
        }

        queue<Point> q;
        q.push(start);
        vector<vector<vector<bool>>> visited(L, vector<vector<bool>>(R, vector<bool>(C, false)));
        visited[start.l][start.r][start.c] = true;

        int ans = -1;
        while (!q.empty()) {
            Point curr = q.front();
            q.pop();

            if (curr.l == end.l && curr.r == end.r && curr.c == end.c) {
                ans = curr.d;
                break;
            }

            for (int i = 0; i < 6; i++) {
                int nl = curr.l + dl[i];
                int nr = curr.r + dr[i];
                int nc = curr.c + dc[i];

                if (nl >= 0 && nl < L && nr >= 0 && nr < R && nc >= 0 && nc < C &&
                    !visited[nl][nr][nc] && dungeon[nl][nr][nc] != '#') {
                    visited[nl][nr][nc] = true;
                    q.push({nl, nr, nc, curr.d + 1});
                }
            }
        }

        if (ans != -1) cout << "Escaped in " << ans << " minute(s)." << endl;
        else cout << "Trapped!" << endl;
    }
    return 0;
}
